import type { EmailMessage } from "./send";

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function layout(body: string): string {
  return `<!doctype html>
<html>
  <body style="margin:0;padding:24px;background:#f6f6f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#111">
    <div style="max-width:480px;margin:0 auto;background:#fff;border-radius:8px;padding:32px">
      ${body}
      <p style="margin-top:32px;font-size:12px;color:#888">Notely</p>
    </div>
  </body>
</html>`;
}

function button(href: string, label: string): string {
  return `<a href="${escapeHtml(href)}" style="display:inline-block;padding:10px 18px;background:#111;color:#fff;border-radius:6px;text-decoration:none">${escapeHtml(label)}</a>`;
}

export function welcomeEmail(params: {
  to: string;
  name: string;
  dashboardUrl: string;
}): EmailMessage {
  const name = escapeHtml(params.name);
  return {
    to: params.to,
    subject: "Welcome to Notely",
    html: layout(`
      <h1 style="font-size:20px;margin:0 0 16px">Welcome, ${name}!</h1>
      <p>Your Notely account is ready. Jump in and start writing notes with your team.</p>
      <p style="margin-top:24px">${button(params.dashboardUrl, "Open Notely")}</p>
    `),
    text: `Welcome, ${params.name}!

Your Notely account is ready. Jump in and start writing notes with your team:
${params.dashboardUrl}

— Notely`,
  };
}

export function passwordResetEmail(params: {
  to: string;
  name: string;
  resetUrl: string;
  expiresInMinutes: number;
}): EmailMessage {
  const name = escapeHtml(params.name);
  return {
    to: params.to,
    subject: "Reset your Notely password",
    html: layout(`
      <h1 style="font-size:20px;margin:0 0 16px">Reset your password</h1>
      <p>Hi ${name}, we received a request to reset your Notely password.</p>
      <p style="margin-top:24px">${button(params.resetUrl, "Choose a new password")}</p>
      <p style="margin-top:24px;font-size:14px;color:#555">This link expires in ${params.expiresInMinutes} minutes. If you didn't request a reset, you can ignore this email.</p>
    `),
    text: `Hi ${params.name},

We received a request to reset your Notely password. Choose a new one here:
${params.resetUrl}

This link expires in ${params.expiresInMinutes} minutes. If you didn't request a reset, you can ignore this email.

— Notely`,
  };
}
