cat > src/lib/users.ts <<'EOF'
import { createHash, randomBytes, randomUUID, scryptSync, timingSafeEqual } from "node:crypto";
import { passwordResetEmail, sendEmail, welcomeEmail } from "@/lib/email";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

// Kept apart from User so hashes never leak into pages that render users.
const passwordHashes = new Map<string, string>();

type PasswordResetToken = { userId: string; expiresAt: number };
// Keyed by SHA-256 of the token, so the raw token only ever exists in the email.
const passwordResetTokens = new Map<string, PasswordResetToken>();
const PASSWORD_RESET_TTL_MINUTES = 60;

function appUrl(path: string): string {
  const base = process.env.APP_URL ?? "http://localhost:3000";
  return new URL(path, base).toString();
}

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = scryptSync(password, salt, 64).toString("hex");
  return `${salt}:${hash}`;
}

export function verifyPassword(userId: string, password: string): boolean {
  const stored = passwordHashes.get(userId);
  if (!stored) return false;
  const [salt, hash] = stored.split(":");
  const expected = Buffer.from(hash, "hex");
  const actual = scryptSync(password, salt, expected.length);
  return timingSafeEqual(expected, actual);
}

function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const normalized = normalizeEmail(email);
  return users.find((u) => u.email === normalized);
}

export async function createUser(input: {
  email: string;
  name: string;
  password?: string;
}): Promise<User> {
  const email = normalizeEmail(input.email);
  if (await getUserByEmail(email)) {
    throw new Error(`A user with email ${email} already exists`);
  }

  const user: User = {
    id: randomUUID(),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  if (input.password) passwordHashes.set(user.id, hashPassword(input.password));

  // The account exists either way; a failed welcome email shouldn't undo signup.
  try {
    await sendEmail(
      welcomeEmail({ to: user.email, name: user.name, dashboardUrl: appUrl("/dashboard") }),
    );
  } catch (err) {
    console.error(`Failed to send welcome email to user ${user.id}`, err);
  }

  return user;
}

// Always resolves without revealing whether the email belongs to an account.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = await getUserByEmail(email);
  if (!user) return;

  // Only the most recent link should work.
  for (const [key, entry] of passwordResetTokens) {
    if (entry.userId === user.id) passwordResetTokens.delete(key);
  }

  const token = randomBytes(32).toString("base64url");
  passwordResetTokens.set(hashToken(token), {
    userId: user.id,
    expiresAt: Date.now() + PASSWORD_RESET_TTL_MINUTES * 60_000,
  });

  const resetUrl = appUrl(`/reset-password?token=${encodeURIComponent(token)}`);
  await sendEmail(
    passwordResetEmail({
      to: user.email,
      name: user.name,
      resetUrl,
      expiresInMinutes: PASSWORD_RESET_TTL_MINUTES,
    }),
  );
}

// Returns true if the token was valid and the password was changed.
export async function resetPassword(token: string, newPassword: string): Promise<boolean> {
  const key = hashToken(token);
  const entry = passwordResetTokens.get(key);
  if (!entry) return false;
  passwordResetTokens.delete(key);
  if (entry.expiresAt < Date.now()) return false;
  if (!(await getUser(entry.userId))) return false;

  passwordHashes.set(entry.userId, hashPassword(newPassword));
  return true;
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  return users[0];
}
EOF
